"""Decoder for crush .cz format, derived from black-box experiments + objdump.

Format (little endian, all fields uint64):
  for c in 0..254:
      count[c]            # number of occurrences of byte value c
      pos[0..count-1]     # ascending file offsets where byte c occurred
The original message is rebuilt by out[pos] = c for every listed position.
Byte value 255 (0xff) is never serialized by crush (loop stops at 254).
"""
import sys

def parse(data):
    groups = {}
    off = 0
    for c in range(255):
        if off + 8 > len(data):
            print(f"!! truncated at char {c} (offset {off})", file=sys.stderr)
            break
        cnt = int.from_bytes(data[off:off+8], 'little')
        off += 8
        if off + 8*cnt > len(data):
            print(f"!! char {c}: count {cnt} exceeds file (offset {off})", file=sys.stderr)
            cnt = (len(data) - off)//8
        positions = [int.from_bytes(data[off+8*i:off+8*i+8], 'little') for i in range(cnt)]
        off += 8*cnt
        if cnt:
            groups[c] = positions
    return groups, off

def decode(data):
    groups, used = parse(data)
    out = {}
    dup = []
    for c, positions in groups.items():
        for p in positions:
            if p in out:
                dup.append((c, p, out[p]))
            out[p] = c
    n = max(out)+1 if out else 0
    buf = bytearray(b'\xff'*n)  # 0xff = never-serialized byte value / hole marker
    for p, c in out.items():
        buf[p] = c
    return bytes(buf), groups, used, dup, n, len(out)

if __name__ == '__main__':
    path = sys.argv[1] if len(sys.argv) > 1 else '/workspace/message.txt.cz'
    data = open(path, 'rb').read()
    buf, groups, used, dup, n, npos = decode(data)
    print(f"file bytes={len(data)} consumed={used} chars_used={len(groups)} "
          f"positions={npos} span={n} max_pos={n-1} duplicates={len(dup)}",
          file=sys.stderr)
    holes = n - npos
    print(f"holes(0xff presumed)={holes}", file=sys.stderr)
    if dup:
        print("dup samples:", dup[:20], file=sys.stderr)
    sys.stdout.buffer.write(buf)
"}

